package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Explicit public snapshots of selected private messages. Reviewers never receive private detail. */
public class PublicCommunityQuestions {
 static final String CONSENT="R8C_PUBLIC_QA_V1",REDACTION="QA_TEXT_REDACTION_V1";
 final ReservationStore db;final OperatorIdentity operators;final CommunityQuestionPolicies policies;final ExperienceModeration experiences;final boolean enabled;final String appId;
 public PublicCommunityQuestions(ReservationStore db,OperatorIdentity operators,CommunityQuestionPolicies policies,ExperienceModeration experiences,boolean enabled,String appId){this.db=db;this.operators=operators;this.policies=policies;this.experiences=experiences;this.enabled=enabled;this.appId=appId;}
 void enabled(){if(!enabled)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"公开问答授权审核尚未开启");}
 static JsonNode input(String raw,String action){var b=CouponInput.parse(raw);switch(action){
  case "preview"->{CouponInput.exact(b,"question_message_id","answer_message_id");CouponInput.id(b.get("question_message_id"));CouponInput.id(b.get("answer_message_id"));}
  case "submit"->{CouponInput.exact(b,"question_message_id","answer_message_id","preview_hash","consent_version","consent");CouponInput.id(b.get("question_message_id"));CouponInput.id(b.get("answer_message_id"));if(!b.path("preview_hash").isTextual()||!b.path("preview_hash").asText().matches("[a-f0-9]{64}")||!CONSENT.equals(b.path("consent_version").asText())||!b.path("consent").isBoolean()||!b.path("consent").asBoolean())throw ReservationInput.bad();}
  case "withdraw"->{CouponInput.exact(b,"expected_revision");CouponInput.id(b.get("expected_revision"));}
  case "moderate"->{CouponInput.exact(b,"expected_revision","decision","reason_code");CouponInput.id(b.get("expected_revision"));String d=b.path("decision").asText();if(!Set.of("APPROVE","REJECT").contains(d)||d.equals("APPROVE")&&!b.get("reason_code").isNull()||d.equals("REJECT")&&(!b.get("reason_code").isTextual()||!PublicReviewTextInput.REASONS.contains(b.path("reason_code").asText())))throw ReservationInput.bad();}
  default->throw ReservationInput.bad();}return b;
 }
 Map<String,Object> owned(VehicleOwner a,long caseId,boolean lock){db.owner(a,lock);return db.one("SELECT * FROM community_qa_case WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),caseId,a.id());}
 Map<String,Object> application(long id,boolean lock){return db.one("SELECT * FROM community_qa_publication WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 private String excerpt(Object text){String all=PublicReviewTextInput.redact(db.mapper.valueToTree(text),2000);return all.codePointCount(0,all.length())>300?all.substring(0,all.offsetByCodePoints(0,300)):all;}
 private Map<String,Object> source(long caseId,long question,long answer,boolean lock){
  String tail=lock?" FOR UPDATE":"";var c=db.one("SELECT * FROM community_qa_case WHERE id=?"+tail,caseId);
  db.one("SELECT id FROM user WHERE id=? AND status=1 AND is_deleted=0"+tail,c.get("owner_id"));
  var car=db.one("SELECT v.model_id FROM vehicle v JOIN model m ON m.id=v.model_id AND m.status=1 AND m.is_deleted=0 JOIN series s ON s.id=m.series_id AND s.status=1 AND s.is_deleted=0 JOIN brand b ON b.id=s.brand_id AND b.status=1 AND b.is_deleted=0 WHERE v.id=? AND v.user_id=? AND v.is_deleted=0"+tail,c.get("vehicle_id"),c.get("owner_id"));
  if(db.parse(c.get("vehicle_snapshot")).path("model_id").asLong()!=number(car,"model_id"))throw CommunityQuestionPolicies.conflict();
  var q=db.one("SELECT * FROM community_qa_message WHERE id=? AND case_id=? AND sender_type='OWNER'"+tail,question,caseId);var a=db.one("SELECT * FROM community_qa_message WHERE id=? AND case_id=? AND sender_type='OPERATOR'"+tail,answer,caseId);
  if(number(q,"sender_id")!=number(c,"owner_id")||question>=answer||!Objects.equals(db.jdbc.queryForObject("SELECT MAX(id) FROM community_qa_message WHERE case_id=? AND sender_type='OWNER' AND id<?",Long.class,caseId,answer),question))throw CommunityQuestionPolicies.conflict();
  CommunityQuestionSource.trustedMessage(db,c,q);CommunityQuestionSource.trustedMessage(db,c,a);
  var proof=q.get("admission_snapshot")==null?db.mapper.nullNode():db.parse(q.get("admission_snapshot"));if(appId.isBlank()||!"VERIFIED_WECHAT".equals(proof.path("identity_source").asText())||!appId.equals(proof.path("identity_app_id").asText()))throw CommunityQuestionPolicies.conflict();
  var preview=Map.<String,Object>of("model_id",car.get("model_id"),"category",c.get("category"),"question_text",excerpt(q.get("body")),"answer_text",excerpt(a.get("body")),"redaction_version",REDACTION);
  return Map.of("case_id",caseId,"owner_id",c.get("owner_id"),"question_message_id",question,"answer_message_id",answer,"question_hash",q.get("source_hash"),"answer_hash",a.get("source_hash"),"preview",preview);
 }
 private String hash(Object value){return CommunityQuestionSource.hash(db,value);}
 private JsonNode previewView(Map<String,Object> r){var binding=db.parse(r.get("source_snapshot"));var p=binding.path("preview");if(!hash(binding).equals(r.get("preview_hash"))||!p.isObject()||p.size()!=5||!p.has("model_id")||!p.has("category")||!p.has("question_text")||!p.has("answer_text")||!p.has("redaction_version")||p.path("model_id").asLong()!=number(r,"model_id")||binding.path("owner_id").asLong()!=number(r,"owner_id")||binding.path("case_id").asLong()!=number(r,"case_id")||binding.path("question_message_id").asLong()!=number(r,"question_message_id")||binding.path("answer_message_id").asLong()!=number(r,"answer_message_id")||!CommunityQuestionSource.canonical(p).toString().equals(CommunityQuestionSource.canonical(db.parse(r.get("preview"))).toString()))return null;return p;}
 private boolean sourceMatches(Map<String,Object> r){try{if(previewView(r)==null)return false;var current=source(number(r,"case_id"),number(r,"question_message_id"),number(r,"answer_message_id"),false);return hash(current).equals(r.get("preview_hash"))&&CommunityQuestionSource.canonical(db.mapper.valueToTree(current)).toString().equals(CommunityQuestionSource.canonical(db.parse(r.get("source_snapshot"))).toString())&&CommunityQuestionSource.canonical(db.mapper.valueToTree(current.get("preview"))).toString().equals(CommunityQuestionSource.canonical(db.parse(r.get("preview"))).toString());}catch(ResponseStatusException e){return false;}}
 private Map<String,Object> receipt(Map<String,Object> r){return Map.of("application_id",r.get("id"),"revision",r.get("revision"),"status",r.get("status"));}
 private Map<String,Object> audit(Map<String,Object> r){var out=new LinkedHashMap<String,Object>(receipt(r));out.put("preview_hash",r.get("preview_hash"));out.put("public_id",r.get("public_id"));return out;}
 private void event(Map<String,Object> r){db.jdbc.update("INSERT INTO community_qa_publication_event(publication_id,revision,status,preview_hash,public_id,occurred_at) VALUES(?,?,?,?,?,?)",r.get("id"),r.get("revision"),r.get("status"),r.get("preview_hash"),r.get("public_id"),"APPROVED".equals(r.get("status"))?r.get("published_at"):time(db.now()));}
 private boolean stateTrusted(Map<String,Object> r){
  if(!CONSENT.equals(r.get("consent_version")))return false;
  var rows=db.jdbc.queryForList("SELECT * FROM community_qa_publication_event WHERE publication_id=? ORDER BY revision DESC LIMIT 1",r.get("id"));if(rows.size()!=1)return false;var e=rows.get(0);
  if("APPROVED".equals(r.get("status"))&&!Objects.equals(iso(r.get("published_at")),iso(e.get("occurred_at"))))return false;
  if(number(e,"is_deleted")!=0||number(e,"revision")!=number(r,"revision")||!Objects.equals(e.get("status"),r.get("status"))||!Objects.equals(e.get("preview_hash"),r.get("preview_hash"))||!Objects.equals(e.get("public_id"),r.get("public_id")))return false;
  var logs=db.jdbc.queryForList("SELECT * FROM audit_log WHERE resource_type='community_qa_publication' AND resource_id=? AND action IN ('PUBLIC_QA_SUBMIT','PUBLIC_QA_MODERATE','PUBLIC_QA_WITHDRAW') ORDER BY id DESC LIMIT 1",r.get("id"));if(logs.size()!=1||number(logs.get(0),"is_deleted")!=0)return false;
  return CommunityQuestionSource.canonical(db.parse(logs.get(0).get("after_state"))).toString().equals(CommunityQuestionSource.canonical(db.mapper.valueToTree(audit(r))).toString());
 }
 private boolean visible(Map<String,Object> r){return enabled&&"APPROVED".equals(r.get("status"))&&r.get("public_id")!=null&&r.get("published_at")!=null&&stateTrusted(r)&&sourceMatches(r);}
 private Map<String,Object> ownView(Map<String,Object> r){var out=new LinkedHashMap<String,Object>(receipt(r));out.put("preview",previewView(r));out.put("public_id",r.get("public_id"));out.put("reason_code",r.get("reason_code"));out.put("visible",visible(r));out.put("created_at",iso(r.get("created_at")));return out;}
 public Map<String,Object> preview(VehicleOwner a,long caseId,JsonNode b){return db.reads.execute(tx->{owned(a,caseId,false);enabled();var s=source(caseId,b.path("question_message_id").asLong(),b.path("answer_message_id").asLong(),false);return Map.of("preview",s.get("preview"),"preview_hash",hash(s));});}
 public Map<String,Object> ownList(VehicleOwner a,long caseId,int p){return db.reads.execute(tx->{owned(a,caseId,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM community_qa_publication WHERE owner_id=? AND case_id=?",Long.class,a.id(),caseId);return page(db.jdbc.queryForList("SELECT * FROM community_qa_publication WHERE owner_id=? AND case_id=? ORDER BY id DESC LIMIT 20 OFFSET ?",a.id(),caseId,(p-1)*20L).stream().map(this::ownView).toList(),total,p,20);});}
 public JsonNode submit(VehicleOwner a,long caseId,String key,JsonNode b){String canonical=com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(key),bodyHash=hash(b);return db.writes.execute(new Actor("user",a.id()),"POST","/api/owner/community/questions/cases/"+caseId+"/publications",key,b,()->{db.owner(a,false);policies.guard();owned(a,caseId,true);},()->{
  var old=db.jdbc.queryForList("SELECT * FROM community_qa_publication WHERE owner_id=? AND submission_key=? FOR UPDATE",a.id(),canonical);if(!old.isEmpty()){var r=old.get(0);if(number(r,"case_id")!=caseId||!bodyHash.equals(r.get("submission_hash")))throw ReservationInput.bad();var data=db.mapper.convertValue(db.parse(r.get("creation_result")),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});return new Change("PUBLIC_QA_SUBMIT","community_qa_publication",number(r,"id"),data,data,data,false);}
  enabled();var s=source(caseId,b.path("question_message_id").asLong(),b.path("answer_message_id").asLong(),true);if(!hash(s).equals(b.path("preview_hash").asText())||!db.jdbc.queryForList("SELECT id FROM community_qa_publication WHERE active_case=? FOR UPDATE",caseId).isEmpty())throw CommunityQuestionPolicies.conflict();
  var preview=(Map<?,?>)s.get("preview");long id=db.insert("INSERT INTO community_qa_publication(owner_id,case_id,question_message_id,answer_message_id,model_id,source_snapshot,preview,preview_hash,consent_version,created_at,submission_key,submission_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",a.id(),caseId,b.path("question_message_id").asLong(),b.path("answer_message_id").asLong(),preview.get("model_id"),db.json(s),db.json(preview),hash(s),CONSENT,time(db.now()),canonical,bodyHash);var r=application(id,true);var data=receipt(r);db.jdbc.update("UPDATE community_qa_publication SET creation_result=? WHERE id=?",db.json(data),id);event(r);return new Change("PUBLIC_QA_SUBMIT","community_qa_publication",id,Map.of(),audit(r),data);
 });}
 public JsonNode withdraw(VehicleOwner a,long id,String key,JsonNode b){return db.writes.execute(new Actor("user",a.id()),"POST","/api/owner/community/question-publications/"+id+"/withdraw",key,b,()->{db.owner(a,false);policies.guard();db.owner(a,true);var r=application(id,true);if(number(r,"owner_id")!=a.id())throw missing();owned(a,number(r,"case_id"),true);},()->{
  var r=application(id,true);long expected=b.path("expected_revision").asLong();if("WITHDRAWN".equals(r.get("status"))&&number(r,"revision")==expected+1&&stateTrusted(r)){var data=receipt(r);return new Change("PUBLIC_QA_WITHDRAW","community_qa_publication",id,data,data,data,false);}
  if("WITHDRAWN".equals(r.get("status"))||number(r,"revision")!=expected)throw CommunityQuestionPolicies.conflict();var before=audit(r);db.jdbc.update("UPDATE community_qa_publication SET status='WITHDRAWN',revision=revision+1 WHERE id=?",id);var after=application(id,true);event(after);return new Change("PUBLIC_QA_WITHDRAW","community_qa_publication",id,before,audit(after),receipt(after));
 });}
 public Map<String,Object> pending(OperatorActor a,int p){return db.reads.execute(tx->{operators.authorize(a,OperatorIdentity.Permission.REVIEW,false);enabled();long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM community_qa_publication WHERE status='PENDING'",Long.class);var items=new ArrayList<Map<String,Object>>();for(var r:db.jdbc.queryForList("SELECT * FROM community_qa_publication WHERE status='PENDING' ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L)){var out=new LinkedHashMap<String,Object>(receipt(r));out.put("preview",previewView(r));out.put("created_at",iso(r.get("created_at")));out.put("source_available",stateTrusted(r)&&sourceMatches(r));items.add(out);}return page(items,total,p,20);});}
 public JsonNode moderate(OperatorActor a,long id,String key,JsonNode b){String target=b.path("decision").asText().equals("APPROVE")?"APPROVED":"REJECTED";return db.writes.execute(new Actor("operator_account",a.id()),"POST","/api/admin/community/question-publications/"+id+"/moderate",key,b,()->{
  operators.authorize(a,OperatorIdentity.Permission.REVIEW,false);policies.guard();operators.authorize(a,OperatorIdentity.Permission.REVIEW,true);enabled();var r=application(id,true);long expected=b.path("expected_revision").asLong();boolean replay=number(r,"revision")==expected+1&&target.equals(r.get("status"));if(!(number(r,"revision")==expected&&"PENDING".equals(r.get("status")))&&!replay||!stateTrusted(r))throw CommunityQuestionPolicies.conflict();
  String reason=b.get("reason_code").isNull()?null:b.path("reason_code").asText();if(replay&&!Objects.equals(reason,r.get("reason_code")))throw CommunityQuestionPolicies.conflict();
  if(target.equals("APPROVED")){var s=source(number(r,"case_id"),number(r,"question_message_id"),number(r,"answer_message_id"),true);if(!hash(s).equals(r.get("preview_hash"))||!sourceMatches(r))throw CommunityQuestionPolicies.conflict();}
 },()->{var r=application(id,true);if(number(r,"revision")==b.path("expected_revision").asLong()+1){var data=receipt(r);return new Change("PUBLIC_QA_MODERATE","community_qa_publication",id,data,data,data,false);}var before=audit(r);db.jdbc.update("UPDATE community_qa_publication SET status=?,revision=revision+1,reason_code=?,public_id=?,published_at=? WHERE id=?",target,b.get("reason_code").isNull()?null:b.path("reason_code").asText(),target.equals("APPROVED")?UUID.randomUUID().toString():null,target.equals("APPROVED")?time(db.now()):null,id);var after=application(id,true);event(after);return new Change("PUBLIC_QA_MODERATE","community_qa_publication",id,before,audit(after),receipt(after));});}
 private Map<String,Object> publicView(Map<String,Object> r){var p=db.parse(r.get("preview"));return Map.of("public_id",r.get("public_id"),"model_id",p.path("model_id").longValue(),"category",p.path("category").asText(),"question_text",p.path("question_text").asText(),"answer_text",p.path("answer_text").asText(),"published_at",iso(r.get("published_at")));}
 public Map<String,Object> list(VehicleOwner a,long vehicle,Long cursor){return db.reads.execute(tx->{var model=experiences.recipient(a,vehicle);enabled();var out=new LinkedHashMap<String,Object>();out.put("vehicle_id",vehicle);out.put("items",List.of());out.put("next_cursor",null);if(model==null)return out;var rows=db.jdbc.queryForList("SELECT * FROM community_qa_publication WHERE status='APPROVED' AND model_id=? AND id<? ORDER BY id DESC LIMIT 21",model,cursor==null?Long.MAX_VALUE:cursor);var items=new ArrayList<Map<String,Object>>();for(int i=0;i<Math.min(20,rows.size());i++)if(visible(rows.get(i)))items.add(publicView(rows.get(i)));out.put("items",items);out.put("next_cursor",rows.size()>20?rows.get(19).get("id"):null);return out;});}
 public Map<String,Object> detail(VehicleOwner a,long vehicle,String publicId){ExperienceModeration.publicId(publicId);return db.reads.execute(tx->{var model=experiences.recipient(a,vehicle);enabled();var rows=db.jdbc.queryForList("SELECT * FROM community_qa_publication WHERE public_id=? AND model_id=?",publicId,model);if(rows.size()!=1||!visible(rows.get(0)))throw missing();return Map.of("vehicle_id",vehicle,"question",publicView(rows.get(0)));});}
}
